; Address-ordered layout — generated by v06c-asm-export (Stage 6.23)
; Every byte of the ROM window is emitted exactly once: instruction,
; RDB data region, or explicit gap_ region.  This is what the build
; consumes; code/code.asm and data/data.asm are read-only views.

; Точка входа ROM (org 0x0100). DI; LXI SP,0100h; CALL 04B5 — установка векторов; LXI H,070D / SHLD 0827 — указатель таблицы палитры; MVI A,03 / STA 071E — счётчик кадров; LXI H,8000h с циклом 0117 (MOV M,D; INX H; до оборачивания) — обнуление всей VRAM 0x8000..0xFFFF; JMP 0863 — продолжение инициализации. Портов не трогает; из ISR не вызывается. Stage 3 (параметры): параметров нет — это стартовая точка, а не подпрограмма, SP только что выставлен (стек пуст, return-адреса нет). Все 4 кандидата abi_scan отвергнуты по телу: HL/DE приходят не извне (LXI H,070Dh @0x0107 и LXI H,8000h @0x0112 задают их до первого чтения; MVI D,00h @0x0113 — внутренний нуль); «memory_argument» — инициализация RAM (SHLD 0827h @0x010A, STA 071Eh @0x010F), а не передача аргумента; кандидат «SHLD 0x033B» фантомный — побайтовый поиск паттерна 22 3B 03 в 0x0100..0x50FF (debug_find_bytecode_sequence) дал 0 совпадений, т.е. такой инструкции в ROM нет (ошибочный раскодированный участок данных).
func_boot_init:
	di
	lxi	sp,0100h
	call	func_install_vectors
	lxi	h,070dh
	shld	var_palette_ramp_ptr
	mvi	a,03h
	sta	var_ramp_frames
	lxi	h,8000h
	mvi	d,00h
lbl_0117:
	mov	m,d
	inx	h
	mov	a,l
	ora	h
	jnz	lbl_0117
	jmp	func_session_state_driver
; Заглушка: единственный RET (C9) @0x0121. Вызывается из func_attract_init_scene (CALL 0x2B08) как пустое место под авторский патч инициализации; на регистры и память не влияет. Stage 4: содержимое не менялось ни в одной из трёх фаз (boot / заставка / игра), вектора прерываний и music-хук сюда ничего не пишут — design-time слот, а не IRQ-хук. Байты 0x0122..0x0123 (MOV A,M; RET) в объект не входят.
func_ret_stub_a:
	ret
; Uncovered ROM bytes — neither code nor an RDB object
gap_0122:
	defb	7Eh,0C9h

; Примитив вывода одного символа: PUSH H; MOV M,A (запись байта по (HL)); STA 082A — кэш записанного значения; если страница адреса H равна 0x54/0x55/0x56 — CALL 0551 (отрисовка 8x8 глифа в 4 битплоскости VRAM); INX H; SHLD 0840 — сохранение курсора; POP H; RET. Параметры: A=код символа, HL=адрес назначения. Портов не трогает (только память), из ISR не вызывается. Самый частый вызываемый примитив текста (22 CALL из кода). Stage 3 (параметры): подтверждены A и HL как два входа. Кандидат memory_argument (STA 082A) отвергнут — это внутренняя ячейка-кэш аккумулятора (STA @0x0126 / LDA @0x0136 в одном теле), вызывающий её не заполняет. Кандидат output A отвергнут: A на выходе = MOV A,H @0x0129 с последующим LDA 082A, контрактом не является. Кандидат output L отвергнут: HL строго восстанавливается (PUSH H @0x0124 / POP H @0x0140), продвижение курсора живёт в [0x0840]; INX H в местах вызова (0x1797, 0x17ED, 0x1E4D) делает сам вызывающий.
func_put_char_glyph:
	push	h
	mov	m,a
	sta	var_scratch_word
	mov	a,h
	cpi	54h
	jz	lbl_0136
	cpi	55h
	jz	lbl_0136
	cpi	56h
lbl_0136:
	lda	var_scratch_word
	cz	func_render_glyph_vram
	inx	h
	shld	0840h
	pop	h
	ret
; Заливка области значением A с отрисовкой глифов: PUSH H; PUSH PSW; MOV M,A; STA 082A; проверка страниц 0x54/0x55/0x56; CZ 0551; INX H; DCX B; цикл 0168 пока BC!=0; SHLD 0840; POP PSW/POP H; RET. Отличие от func_put_char_glyph — сохранность HL/PSW и счётчик BC. Используется для очистки текстовых страниц пробелом (0x20) и заливки 0xC0. Stage 3 (параметры): подтверждены три входа — A=заполняющий байт, HL=адрес, BC=длина (16 бит, DCX B + MOV A,B/ORA C/JNZ). Кандидат memory_argument (STA 082A) отвергнут как и у 0x0124 (кэш A). Кандидаты output A и output L отвергнуты: PSW и HL восстанавливаются в хвосте (POP PSW/POP H), то есть на выходе вызывающий видит свои же значения; «конец заливаемой области» наружу не возвращается, в [0x0840] кладётся только курсор.
func_fill_char_glyph:
	push	h
label_0143:
	push	psw
	mov	m,a
	sta	var_scratch_word
	mov	a,h
	cpi	54h
	jz	lbl_0155
	cpi	55h
	jz	lbl_0155
	cpi	56h
lbl_0155:
	lda	var_scratch_word
	cz	func_render_glyph_vram
	inx	h
	dcx	b
	mov	a,b
	ora	c
	jnz	lbl_0168
	shld	0840h
	pop	psw
	pop	h
	ret
lbl_0168:
	pop	psw
	jmp	label_0143
; Uncovered ROM bytes — neither code nor an RDB object
gap_016C:
	defb	0E5h,7Eh,12h,23h,13h,0Bh,79h,0B0h
	defb	0C2h,6Dh,01h,22h,40h,08h,0E1h,0C9h

; Копирование блока из (HL) в (DE) длиной BC байт (счётчик 16-битный: DCX B + MOV A,C / ORA B / JNZ @0x0199..0x019B, выход при BC=0). Первая команда XCHG @0x017C меняет роли: дальше HL = приёмник, DE = источник. Каждый записанный байт, если приёмник лежит в текстовых страницах (H = 0x54/0x55/0x56), дополнительно выводится глифом через func_render_glyph_vram (CZ 0x0551 @0x0193). Конечный адрес приёмника сохраняется в [0x0840] (SHLD @0x019E). Примеры вызова: 0x2B3B (LXI H,3114; LXI D,6000; LXI B,0400), 0x1C90 (LXI B,0012), 0x1FC7 (LXI B,02C0), 0x27B6 (LXI B,000C). Портов не трогает, из ISR не вызывается. Stage 3 (исправления к Stage 2): (1) длина — пара BC (16 бит), а не «B байт»; (2) прежнее «после RET HL = конец приёмника» неверно: PUSH H @0x017D выполняется уже после XCHG, поэтому POP H @0x01A1 возвращает HL = базовый адрес приёмника, а конец приёмника уходит только в [0x0840]; DE на выходе = конец источника, BC = 0, A = последний записанный байт. (3) Ни один из 10 вызывающих (0x174A, 0x1C93, 0x1FCA, 0x2219, 0x22FC, 0x23D3, 0x23FB, 0x27B9, 0x2B3B, 0x2B47) выходящие HL/DE не использует — сразу POP H/POP D или новый LXI H/LXI D. Поэтому кандидаты output D/output E/output L отвергнуты: параметров-результатов у функции нет, есть три входных 16-битных параметра HL/DE/BC.
func_copy_text_block:
	xchg
	push	h
lbl_017e:
	ldax	d
	mov	m,a
	sta	var_scratch_word
	mov	a,h
	cpi	54h
	jz	lbl_0190
	cpi	55h
	jz	lbl_0190
	cpi	56h
lbl_0190:
	lda	var_scratch_word
	cz	func_render_glyph_vram
	inx	h
	inx	d
	dcx	b
	mov	a,c
	ora	b
	jnz	lbl_017e
	shld	0840h
	pop	h
	ret
; Uncovered ROM bytes — neither code nor an RDB object
gap_01A3:
	defb	0C9h

; Заглушка: одиночный RET (C9) @0x01A4; рядом 0x01A3 и 0x01A7 — ещё по одному C9, отдельных объектов не имеют. Вызов из func_attract_init_scene (CALL 0x2B02). Stage 4: проверено в фазах boot / заставка / игра — везде C9, адрес обработчика прерывания сюда не записывался, слот не является IRQ-точкой.
func_ret_stub_b:
	ret
; Заглушка: одиночный RET (C9) @0x01A5, первый вызов func_attract_init_scene (CALL 0x2AFF). Побочных эффектов нет, служит точкой встраивания инициализации. Stage 4: в фазах boot / заставка / игра содержимое не менялось (C9), обработчики прерываний сюда не монтируются.
func_ret_stub_c:
	ret
; Заглушка: одиночный RET (C9) @0x01A6. Вызывается из цикла аттракта (0x25A7: CALL 0x01A6, сразу после CALL 0x2AFF). Побочных эффектов нет. Stage 4: в фазах boot / заставка / игра здесь по-прежнему C9 — ни вектора, ни music-хук 0x04EE сюда адрес обработчика не записывают.
func_ret_stub_d:
	ret
label_01A7:
	ret
; Проверка активности строки клавиатуры: DCR A / JM — содержательная обработка только при A=0 (при A>0 функция возвращает 0). Для A=0 читается элемент кольца опроса [0x081F+7] = [0x0826] (CALL func_key_ring_peek 0x01E6), выделяется бит 7 (ANI 0x80) и возвращается 0xFF, если бит 7 СБРОШЕН (линия активна, ключ активный-низкий), и 0, если бит 7 установлен. Портов сама не читает — данные готовит ISR опроса клавиатуры. Из ISR не вызывается. Stage 3 (параметры): подтверждён единственный вход A=номер линии (места вызова задают его: LDA 7C07 @0x0E82, MVI A,00/01/02 @0x2AB3/0x2AC0/0x2ACE). Кандидат output A параметром не является — перенесён в returns.
func_key_strobe_state:
	dcr	a
	jm	lbl_01ae
	xra	a
	ret
lbl_01ae:
	mvi	a,07h
	call	func_key_ring_peek
	ani	80h
	jz	lbl_01ba
	xra	a
	ret
lbl_01ba:
	cma
	ret
; Декод кода нажатой клавиши: содержательная обработка только при A=0 (при A>0 возвращает 0). Для A=0 читается элемент кольца опроса [0x081F] (CALL func_key_ring_peek 0x01E6), старший ниббл выделяется четырьмя RRC + ANI 0F и используется как индекс таблицы переводов 0x01D5 (16 байт: 00 03 05 04 07 00 06 05 01 02 00 03 08 01 07 00); результат возвращается в A. Коды 1..8 соответствуют служебным клавишам (стрелки/SPACE) согласно матрице ВВ55. Портов не трогает, из ISR не вызывается. Stage 3 (параметры): подтверждён вход A=номер линии; кандидат output A — это результат, перенесён в returns.
func_key_code_decode:
	dcr	a
	jm	lbl_01c2
	xra	a
	ret
lbl_01c2:
	xra	a
	call	func_key_ring_peek
	rrc
	rrc
	rrc
	rrc
	ani	0fh
	lxi	h,01d5h
	mov	e,a
	mvi	d,00h
	dad	d
	mov	a,m
	ret
