gap_01D5:
	defb	00h,03h,05h,04h,07h,00h,06h,05h
	defb	01h,02h,00h,03h,08h,01h,07h,00h

; Заглушка: одиночный RET (C9) @0x01E5. Вызывается как пустой слот из func_delay_ramp_on (CALL 0x01E5 @0x189C) и из func_blink_step_delay (CALL 0x01E5 @0x2D68), в A передаётся фаза мигания 0xFF/0x00. Памяти и портов не трогает, из ISR не вызывается. Stage 4 (закрыть open question): снято в трёх фазах boot / заставка / игра — всегда C9, запись адреса обработчика не наблюдалась; единственный runtime-патч кода в цепочке прерываний это слот 0x04EE. Выход ABI-вопроса: обработчик сюда не подставлялся, так что «пришедший от обработчика ABI» для этого слота не определён.
func_ret_stub_e:
	ret
; Чтение элемента кольца результатов опроса клавиатуры: PUSH H; LXI H,081F; CALL 03D2 (HL := HL + A); MOV A,M; POP H; RET — возвращает байт [0x081F+A]. Это строб-код клавиатурной матрицы, который записывает обработчик кадра VBlank 0x04F7 (OUT 00=0x8A — строб, OUT 03 — выбор строки, IN 02 — чтение порта C КР580ВВ55 #1). Портов сама функция не трогает. Вызывается из func_key_strobe_state (0x01B0), func_key_code_decode (0x01C3), func_probe_control_keys (0x122E, 0x1249). Stage 3 (параметры): единственный параметр — A=индекс; кандидат «input L» отвергнут (HL задаётся внутри: LXI H,081Fh @0x01E7 до любого чтения L), кандидат «output H» отвергнут (POP H @0x01EF возвращает HL вызывающего, функция его не меняет).
func_key_ring_peek:
	push	h
	lxi	h,081fh
	call	func_add_a_to_hl
	mov	a,m
	pop	h
	ret
label_01F0:
	ret
; Сброс таблицы ячеек поля: LXI H,067E; MVI C,05; цикл 0x01F6 — MVI M,0xD1; INX H x4; DCR C; JNZ, т.е. заполняет 5 записей со stride 4 кодом 0xD1 (пустая/фоновая ячейка). Затем MVI A,01; STA 071F — взвод флага перерисовки; RET. Вызывается из func_init_attract_data (CALL 01F1 @0x2B0E). Портов не трогает. Stage 3 (параметры): параметров нет. Оба кандидата (output C, output H) отвергнуты: C — внутренний счётчик итераций (MVI C,05h @0x01F4, доходит до 0), H — часть зашитого адреса таблицы (LXI H,067Eh @0x01F1); ни один вызывающий эти регистры после CALL не читает.
func_reset_cell_table:
	lxi	h,067eh
	mvi	c,05h
lbl_01f6:
	mvi	m,0d1h
	inx	h
	inx	h
	inx	h
	inx	h
	dcr	c
	jnz	lbl_01f6
	mvi	a,01h
	sta	var_field_dirty_flag
	ret
; Диспетчер звуковых команд КР580ВИ53: PUSH H; PUSH D; PUSH PSW; LXI H,0217; ANI 0F; ADD A; CALL 03D2 — индексация таблицы из 16 адресов переходов; MOV D,M; INX H; MOV H,M; MOV L,D; PCHL. Все команды завершаются общим возвратом в 0x02B8 (POP PSW; POP D; POP H; RET); команда 7 уходит в подтаблицу 0x02E0 (её обработчик 0x02B5). Обработчики пишут порт 0x08 (управляемое слово 0x36/0x76/0xB6) и порты счётчиков 0x09/0x0A/0x0B, хранят лажи в RAM 0x03C7..0x03D1, делают bit-bang OUT 0x00 в 0x037E. Около 60 вызовов из кода (звуки игры и мелодии); прямо из ISR не вызывается, но дёргается из музыкального хука 0x2EFB через wrapper func_sound_cmd_call (0x2F30). Stage 3 (параметры): A=код команды (0..15) и E=параметр команды; HL/DE/PSW сохраняются и восстанавливаются, то есть не аргументы. Кандидаты input B/C/D/H/L отвергнуты: PUSH H / PUSH D / PUSH PSW @0x0206..0x0209 — сохранение контекста, HL перезадаётся внутренним LXI H,0217h @0x020B; «доказательства» через STAX B получены сканером на ошибочно раскодированных байтах таблицы переходов 0x0217..0x0236 (таблица слов). Кандидат memory_argument STA 0x03C7 — рабочая область команд (лажи), а не приём аргумента; STA 0x25E7 фантомный — паттерн 32 E7 25 в 0x0100..0x50FF не найден (0 совпадений, debug_find_bytecode_sequence), по адресу 0x25E7 в реальности стоит SHLD 0827h. ИСПРАВЛЕНО (Stage 9a): ранее здесь значилось «масштаб периода x7 в 0x0258» — это неверно, масштабирование ×12. Факт: последовательность @0x0258..0x0261 = DAD H; MOV E,L; MOV D,H; DAD H; DAD D; DAD H, то есть HL -> HL*2 -> (DE)=HL*2 -> HL*4 -> +HL*2 = HL*6 -> HL*2 = ×12 от периода; ENTRY-точка 0x024B вызывает её после чтения слова из data_note_freq_table_title @0x301C. Живое подтверждение трассой на заставке: код дорожки 0x33 -> период 1135 (0x046F) -> HL=0x3534=13620 = 12*1135 -> OUT 0x0B,0x34 и OUT 0x0B,0x35 (seq 19536200/19536202). Частота: f = 1 497 600 Гц / 12 / period = 124800/period Гц; для снятого случая 124800/1135 = 109.96 Гц = A2 (440 Гц·2^-3.5).
func_sound_cmd_dispatch:
	push	h
	push	d
	push	psw
	lxi	h,0217h
	ani	0fh
	add	a
	call	func_add_a_to_hl
	mov	d,m
	inx	h
	mov	h,m
	mov	l,d
	pchl
